<?php require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/chat.php';$u=require_permission('NHAN_CHAT');$id=(int)get('id');$h=conversation($id,$u);handle_form(function()use($u,$id){$h=conversation($id,$u);must($h['trang_thai']!=='DA_KET_THUC','Hội thoại đã kết thúc.');$cfg=post('cau_hinh');must(db_one('SELECT 1 FROM cau_hinh_xe WHERE ma_cau_hinh=? AND hien_thi=1',[$cfg]),'Cấu hình không hợp lệ.');$date=valid_date(post('han'));must(strtotime($date)>time(),'Hạn báo giá phải ở tương lai.');execute('INSERT INTO bao_gia(ma_hoi_thoai,nhan_vien_id,ma_cau_hinh,gia_chot,hieu_luc_den,dieu_kien)VALUES(?,?,?,?,?,?)',[$id,$u['id'],$cfg,vnd(post('gia')),$date,valid_text(post('dieu_kien'),4000,false)]);audit('LAP_BAO_GIA','bao_gia',(string)insert_id());},'nhan_vien/bao_gia.php?id='.$id);page_start('Lập báo giá · hội thoại #'.$id);echo '<div class="panel">';token_form();select_field('cau_hinh','Cấu hình',choices('SELECT ma_cau_hinh,ten_cau_hinh FROM cau_hinh_xe WHERE hien_thi=1','ma_cau_hinh','ten_cau_hinh'),$h['ma_cau_hinh'],true);field('gia','Giá thỏa thuận (đ)','','number','required min="1"');field('han','Hiệu lực đến',date('Y-m-d\TH:i',time()+86400),'datetime-local','required');textarea('dieu_kien','Điều kiện báo giá');echo '<button>Gửi báo giá</button></form></div>';page_end();
